int mtmips_pinmux_group_set ( struct udevice * dev , unsigned int group_selector , unsigned int func_selector ) { struct mtmips_pinctrl_priv * priv = dev_get_priv ( dev ) ; const struct mtmips_pmx_group * grp = & priv -> groups [ group_selector ] ; const struct mtmips_pmx_func * func = priv -> funcs [ func_selector ] ; int i ; for ( i = 0 ; i < grp -> nfuncs ; i ++ ) { if ( ! strcmp ( grp -> funcs [ i ] . name , func -> name ) ) { mtmips_pinctrl_reg_set ( priv , grp -> reg , grp -> shift , grp -> mask , grp -> funcs [ i ] . value ) ; return 0 ; } } return - EINVAL ; } 